"""Single-file V54 Kaggle submission."""
import base64
import importlib.util
from pathlib import Path
import sys
import tempfile
import zipfile

_PAYLOAD = ''
_ROOT = Path(tempfile.mkdtemp(prefix="v54_agent_"))
_ZIP = _ROOT / "agent.zip"
_ZIP.write_bytes(base64.b64decode(_PAYLOAD))
with zipfile.ZipFile(_ZIP) as _ARCHIVE:
    _ARCHIVE.extractall(_ROOT)
_SPEC = importlib.util.spec_from_file_location("v54_embedded_root", _ROOT / "main.py")
if _SPEC is None or _SPEC.loader is None:
    raise RuntimeError("cannot load embedded V54 archive")
_MODULE = importlib.util.module_from_spec(_SPEC)
sys.modules[_SPEC.name] = _MODULE
_SPEC.loader.exec_module(_MODULE)

def kaggle_submission_agent(obs, config=None):
    """Return the embedded V54 action."""
    return _MODULE.kaggle_submission_agent(obs, config)

def agent(obs, config=None):
    """Expose Kaggle's alternative conventional entry point."""
    return kaggle_submission_agent(obs, config)
